export type MuseumId = 'historico' | 'transportes' | 'automovil' | 'otros';

export interface SalaTematica {
  id: string;
  title: string;
  stopIds: string[];
  /** Parada introductoria de la sala (la que da nombre/abre la sala). Se muestra en el renglón-título y NO se repite en el listado. */
  introStopId?: string;
}

export interface MuseumArea {
  id: MuseumId;
  title: string;
  shortTitle: string;
  description: string;
  image: string;
  introStopId: string;
  hasTour: boolean;
  salas: SalaTematica[];
}

export interface TourStop {
  id: string;
  stopNumber: number;
  title: string;
  subtitle: string;
  museum: MuseumId;
  salaId?: string;
  image: string;
  audio: string;
  text: string;
  locucion: string;
}

